<script setup lang="ts">import {ref} from 'vue';const drawer=ref(false),error=ref('');async function fullscreen(){try{await document.documentElement.requestFullscreen()}catch{error.value='请使用浏览器全屏菜单'}};</script><template><main><header>✳ 随机一下 <button @click="fullscreen">进入全屏 ↗</button></header><section><small>让惊喜，发生在此刻</small><h1>等待活动连接</h1><div class="gift">🎁</div><p>由手机创建活动后，在这里连接大屏</p><p class="muted">工程预览 · 尚未接入云端同步</p><p>{{error}}</p></section><button class="handle" @click="drawer=!drawer">本场进度 ‹</button><aside v-if="drawer"><button @click="drawer=false">收起 →</button><h2>本场进度</h2><p>尚无活动</p></aside></main></template><style>body{margin:0;background:#15131e;color:#f5f2ff;font-family:system-ui}main{min-height:100vh}header{padding:28px 40px;display:flex;justify-content:space-between;font-size:22px}button{background:#30273f;color:#eee;border:1px solid #57436c;border-radius:12px;padding:12px 20px;cursor:pointer}section{text-align:center;padding:8vh 24px}small{color:#bba9df;letter-spacing:6px}h1{font-size:clamp(36px,6vw,80px)}.gift{font-size:100px}.muted{color:#958aa8}.handle{position:fixed;right:0;top:50%;writing-mode:vertical-rl}aside{position:fixed;right:0;top:0;bottom:0;width:300px;background:#24202e;padding:28px;box-sizing:border-box}</style>